    "faqPage": {
      "@context": "https://schema.org",
      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "What is the most common 30/60/90 onboarding plan mistake?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Vague goals. 'Understand the product' cannot be checked, so it passes review and fails at day 30. Write observable outcomes instead — for example, 'can demo the core flow to a peer' — so each window has a real test."
          }
        },
        {
          "@type": "Question",
          "name": "Why are named check-ins important?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "A plan with goals but no check-ins assumes the manager will remember to look, and they often do not. Naming an owner and a week for each check-in (week 1, week 4, week 12) turns the plan into a calendar that reminds, not a doc that decays."
          }
        },
        {
          "@type": "Question",
          "name": "Should junior and senior hires use the same plan?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. One generic plan sets the wrong bar for both. Role-tune the plan to Junior, Mid, Senior, or Manager so day-60 expectations match the hire's level."
          }
        },
        {
          "@type": "Question",
          "name": "Does work mode change the onboarding plan?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "It changes the first-week checklist. Remote, onsite, and hybrid hires differ in access, intro meetings, and where the handbook lives. The learn/do/own structure stays the same; the logistics differ."
          }
        },
        {
          "@type": "Question",
          "name": "Does a well-written plan guarantee the hire succeeds?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. Avoiding these mistakes makes expectations explicit and check-ins real, but it does not guarantee retention or success. Outcomes depend on the manager, the team, the role, and the individual."
          }
        }
      ]
    }
